pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    Attacker attacker;

    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 amount, address depositor) public {
        amount = bound(amount, 1, 1 ether);
        if (depositor == address(0)) depositor = address(1);

        attacker = new Attacker(c);

        vm.deal(depositor, amount);
        vm.prank(depositor);
        c.deposit{value: amount}();

        uint256 before = address(c).balance;
        vm.assume(before >= amount);

        vm.deal(address(attacker), amount);
        vm.prank(address(attacker));
        c.deposit{value: amount}();

        uint256 mid = address(c).balance;
        vm.assume(mid >= before + amount);

        vm.prank(address(attacker));
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(address(c).balance == mid - amount);
        } else {
            assertTrue(ok);
        }
    }
}

